class Solution {
    int atMost(vector<int>& nums,int limit){
        if(limit<0)return 0;
        int left=0,sum=0,count=0;
        for(int right=0;right<(int)nums.size();++right){
            sum+=nums[right];
            while(sum>limit)sum-=nums[left++];
            count+=right-left+1;
        }
        return count;
    }
